import{_ as s,C as k,o as e,c as l,a2 as t,b as o,w as n,a as r,E as d,a3 as u}from"./chunks/framework.C-KFX0n7.js";const f=JSON.parse('{"title":"Autentikasi & Keamanan API","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"api/autentikasi.md","filePath":"api/autentikasi.md"}'),p={name:"api/autentikasi.md"};function h(g,a,m,b,c,A){const i=k("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="autentikasi-keamanan-api" tabindex="-1">Autentikasi &amp; Keamanan API <a class="header-anchor" href="#autentikasi-keamanan-api" aria-label="Permalink to &quot;Autentikasi &amp; Keamanan API&quot;">​</a></h1><blockquote><p>Sebelum dapat memanggil endpoint manapun, Anda membutuhkan sebuah <strong>Token Akses</strong>. Halaman ini menjelaskan apa itu token, cara mendapatkannya, dan cara menggunakannya dengan benar dan aman.</p></blockquote><hr><h2 id="apa-itu-token-dan-mengapa-dibutuhkan" tabindex="-1">Apa Itu Token dan Mengapa Dibutuhkan? <a class="header-anchor" href="#apa-itu-token-dan-mengapa-dibutuhkan" aria-label="Permalink to &quot;Apa Itu Token dan Mengapa Dibutuhkan?&quot;">​</a></h2><p>Bayangkan token seperti <strong>kartu akses gedung kantor</strong>. Setiap kali Anda masuk, Anda menempelkan kartu ke sensor — sensor itu memverifikasi identitas Anda. Token API bekerja persis sama: ia membuktikan kepada server bahwa Anda adalah pengguna sah yang telah login.</p><p>Tanpa token, semua request akan ditolak dengan pesan <code>401 Unauthorized</code>.</p><p>Ada dua konsep yang perlu dipahami:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Konsep</th><th style="text-align:left;">Pertanyaan yang Dijawab</th><th style="text-align:left;">Kode Error Jika Gagal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Autentikasi</strong></td><td style="text-align:left;"><em>Siapa kamu?</em> — Verifikasi identitas lewat token</td><td style="text-align:left;"><code>401 Unauthorized</code></td></tr><tr><td style="text-align:left;"><strong>Otorisasi</strong></td><td style="text-align:left;"><em>Apa yang boleh kamu lakukan?</em> — Cek hak akses (permission)</td><td style="text-align:left;"><code>403 Forbidden</code></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Token hanya membuktikan Anda sudah login. Tapi setiap endpoint juga membutuhkan <strong>izin (permission)</strong> khusus. Memiliki token tidak otomatis memberikan akses ke semua fitur — hubungi Admin jika Anda menerima <code>403</code>.</p></div><hr><h2 id="alur-mendapatkan-akses" tabindex="-1">Alur Mendapatkan Akses <a class="header-anchor" href="#alur-mendapatkan-akses" aria-label="Permalink to &quot;Alur Mendapatkan Akses&quot;">​</a></h2>',11)),(e(),o(u,null,{default:n(()=>[d(i,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Anda%20(Developer)%22%5D%20--%3E%20B%5B%22Login%20ke%20Aplikasi%5CnTeken%20Heula%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Buka%20Halaman%20Profil%20%2F%20API%20Token%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Generate%20%2F%20Salin%20Token%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Gunakan%20Token%20di%20Header%5CnAuthorization%3A%20Bearer%20...%22%5D%0A%20%20%20%20E%20--%3E%20F%7B%7B%22Akses%20API%20Berhasil%20%E2%9C%85%22%7D%7D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t(`<hr><h2 id="langkah-1-—-login-ke-aplikasi" tabindex="-1">Langkah 1 — Login ke Aplikasi <a class="header-anchor" href="#langkah-1-—-login-ke-aplikasi" aria-label="Permalink to &quot;Langkah 1 — Login ke Aplikasi&quot;">​</a></h2><p>Buka aplikasi Teken Heula di browser Anda dan login menggunakan akun SSO UPI atau akun yang telah diberikan oleh Administrator.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Akun Anda harus sudah aktif dan memiliki izin akses API dari Administrator sebelum dapat melanjutkan. Jika belum, hubungi tim IT atau Admin sistem.</p></div><hr><h2 id="langkah-2-—-salin-token-akses-anda" tabindex="-1">Langkah 2 — Salin Token Akses Anda <a class="header-anchor" href="#langkah-2-—-salin-token-akses-anda" aria-label="Permalink to &quot;Langkah 2 — Salin Token Akses Anda&quot;">​</a></h2><p>Setelah login, ikuti langkah berikut:</p><ol><li>Klik ikon profil Anda di pojok kanan atas.</li><li>Pilih menu <strong>&quot;Profil&quot;</strong> atau <strong>&quot;API Token&quot;</strong>.</li><li>Klik tombol <strong>&quot;Generate Token&quot;</strong> jika belum ada, atau <strong>salin</strong> token yang sudah ada.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Jaga kerahasiaan token Anda.</strong> Token bersifat seperti kata sandi. Jangan pernah meletakkannya di dalam kode yang di-<em>commit</em> ke Git, atau membagikannya melalui chat / email.</p></div><hr><h2 id="langkah-3-—-gunakan-token-di-setiap-request" tabindex="-1">Langkah 3 — Gunakan Token di Setiap Request <a class="header-anchor" href="#langkah-3-—-gunakan-token-di-setiap-request" aria-label="Permalink to &quot;Langkah 3 — Gunakan Token di Setiap Request&quot;">​</a></h2><p>Setelah mendapatkan token, sertakan di setiap request API pada bagian <strong>Header</strong>:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;TOKEN_ANDA_DI_SINI&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span></code></pre></div><p>Contoh menggunakan <code>cURL</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://tekenheula.upi.edu/api/sign-language-certs/abc-123&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9...&quot;</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Di aplikasi seperti <strong>Postman</strong> or <strong>Insomnia</strong>, Anda cukup isi bagian <em>Authorization</em> dengan tipe <strong>Bearer Token</strong>, lalu tempelkan token Anda di kolom yang tersedia — tidak perlu menulis manual di Header.</p></div><hr><h2 id="kode-error-terkait-autentikasi" tabindex="-1">Kode Error Terkait Autentikasi <a class="header-anchor" href="#kode-error-terkait-autentikasi" aria-label="Permalink to &quot;Kode Error Terkait Autentikasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Kode</th><th style="text-align:left;">Arti</th><th style="text-align:left;">Penyebab Umum</th><th style="text-align:left;">Yang Harus Dilakukan</th></tr></thead><tbody><tr><td style="text-align:left;"><code>401 Unauthorized</code></td><td style="text-align:left;">Token tidak dikenali</td><td style="text-align:left;">Token hilang, salah ketik, atau sudah kadaluarsa</td><td style="text-align:left;">Salin ulang token dari halaman profil</td></tr><tr><td style="text-align:left;"><code>403 Forbidden</code></td><td style="text-align:left;">Tidak memiliki hak akses</td><td style="text-align:left;">Token valid, tapi permission tidak ada</td><td style="text-align:left;">Hubungi Admin untuk meminta izin akses</td></tr></tbody></table><hr><h2 id="praktik-keamanan-terbaik" tabindex="-1">Praktik Keamanan Terbaik <a class="header-anchor" href="#praktik-keamanan-terbaik" aria-label="Permalink to &quot;Praktik Keamanan Terbaik&quot;">​</a></h2><p>Ikuti panduan berikut untuk menjaga keamanan integrasi Anda:</p><ul><li>❌ <strong>Jangan</strong> menyimpan token langsung di dalam kode (<code>hardcode</code>).</li><li>✅ Simpan token di <strong>Environment Variable</strong> (<code>.env</code>) dan baca dari sana.</li><li>✅ Rutin <strong>perbarui (rotate) token</strong> secara berkala, terutama jika ada anggota tim yang keluar.</li><li>✅ Gunakan token yang berbeda untuk setiap lingkungan (<em>Development</em> vs <em>Production</em>).</li><li>❌ <strong>Jangan</strong> membagikan token melalui WhatsApp, Slack, atau media komunikasi yang tidak terenkripsi.</li></ul><hr><h2 id="pertanyaan-umum-faq" tabindex="-1">Pertanyaan Umum (FAQ) <a class="header-anchor" href="#pertanyaan-umum-faq" aria-label="Permalink to &quot;Pertanyaan Umum (FAQ)&quot;">​</a></h2><p><strong>❓ Berapa lama token berlaku sebelum kadaluarsa?</strong> Token berlaku selama sesi login aktif. Jika Anda logout atau token dicabut oleh Admin, token tersebut tidak akan bisa digunakan lagi dan Anda perlu mendapatkan token baru.</p><p><strong>❓ Apa yang harus saya lakukan jika token saya bocor atau diketahui orang lain?</strong> Segera hubungi Admin untuk mencabut (<em>revoke</em>) token tersebut, lalu generate token baru dari halaman profil Anda.</p><p><strong>❓ Apakah satu token bisa digunakan untuk semua endpoint API?</strong> Token mengidentifikasi identitas Anda, namun akses ke endpoint tertentu tetap bergantung pada <strong>permission</strong> yang diberikan Admin ke akun Anda. Satu token bisa digunakan ke semua endpoint yang sudah diizinkan.</p><p><strong>❓ Kenapa saya mendapat error <code>403</code> padahal token saya benar?</strong> Artinya token Anda valid (identitas dikenali), tapi akun Anda belum memiliki izin (<em>permission</em>) untuk endpoint tersebut. Hubungi Administrator untuk meminta penambahan permission yang sesuai.</p>`,29))])}const T=s(p,[["render",h]]);export{f as __pageData,T as default};
